<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {api,type ProductSummary,type PromotionRule} from '../api'
import {formatVnd} from '../format'
import {t} from '../i18n'
const rules=ref<PromotionRule[]>([]),products=ref<ProductSummary[]>([]),busy=ref(false),error=ref('')
const mode=ref<PromotionRule['acquisitionMode']>('AUTOMATIC'),code=ref(''),discoverable=ref(false),summary=ref(''),terms=ref('')
const type=ref<PromotionRule['effectType']>('ITEM_PERCENT'),name=ref(''),value=ref(10),minimum=ref<number>(),buy=ref<number>(),globalLimit=ref<number>(),customerLimit=ref<number>(),priority=ref(10),productIds=ref<string[]>([]),familyId=ref<string>(),revisionNumber=ref(1),editingId=ref<string>(),validFrom=ref(new Date().toISOString().slice(0,16)),validTo=ref('')
const isVoucher=computed(()=>mode.value!=='AUTOMATIC')
const layer=computed<PromotionRule['layer']>(()=>type.value.startsWith('ITEM_')?'ITEM':type.value.startsWith('ORDER_')?'ORDER_AUTOMATIC':'SHIPPING')
const effects=computed<PromotionRule['effectType'][]>(()=>isVoucher.value?['ORDER_PERCENT','ORDER_FIXED','FREE_SHIPPING']:['ITEM_PERCENT','ITEM_FIXED','ORDER_PERCENT','ORDER_FIXED','FREE_SHIPPING'])
async function load(){busy.value=true;error.value='';try{[rules.value,products.value]=await Promise.all([api.promotions(),api.products()])}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function reset(){name.value='';familyId.value=undefined;revisionNumber.value=1;editingId.value=undefined;mode.value='AUTOMATIC';code.value='';discoverable.value=false;summary.value='';terms.value='';type.value='ITEM_PERCENT';productIds.value=[]}
async function save(){busy.value=true;error.value='';try{const draft={familyId:familyId.value,revisionNumber:revisionNumber.value,name:name.value,layer:layer.value,effectType:type.value,percentageValue:type.value.endsWith('PERCENT')?value.value:undefined,fixedAmount:type.value.endsWith('FIXED')?value.value:undefined,minimumSpendAmount:minimum.value,buyQuantity:layer.value==='ITEM'?buy.value:undefined,globalUsageLimit:globalLimit.value,perCustomerUsageLimit:customerLimit.value,priority:priority.value,validFrom:new Date(validFrom.value).toISOString(),validTo:validTo.value?new Date(validTo.value).toISOString():undefined,productIds:layer.value==='ITEM'?productIds.value:[],customerSummary:isVoucher.value?summary.value:undefined,customerTerms:isVoucher.value?terms.value:undefined,acquisitionMode:mode.value,normalizedCode:mode.value==='CODE'?code.value:undefined,publiclyDiscoverable:mode.value==='AUTOMATIC'?false:discoverable.value};if(editingId.value)await api.editPromotion(editingId.value,draft);else await api.createPromotion(draft);reset();await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function fill(r:PromotionRule){familyId.value=r.familyId;name.value=r.name;mode.value=r.acquisitionMode;code.value=r.normalizedCode??'';discoverable.value=r.publiclyDiscoverable;summary.value=r.customerSummary??'';terms.value=r.customerTerms??'';type.value=r.effectType;value.value=r.percentageValue??r.fixedAmount??0;minimum.value=r.minimumSpendAmount;buy.value=r.buyQuantity;globalLimit.value=r.globalUsageLimit;customerLimit.value=r.perCustomerUsageLimit;priority.value=r.priority;productIds.value=[...r.productIds];validFrom.value=new Date(r.validFrom).toISOString().slice(0,16);validTo.value=r.validTo?new Date(r.validTo).toISOString().slice(0,16):'';window.scrollTo({top:0,behavior:'smooth'})}
function edit(r:PromotionRule){fill(r);editingId.value=r.id;revisionNumber.value=r.revisionNumber}
function revise(r:PromotionRule){fill(r);editingId.value=undefined;revisionNumber.value=r.revisionNumber+1}
async function transition(r:PromotionRule,action:'publish'|'retire'|'invalidate'){if(action==='invalidate'&&!confirm(t('Invalidate this revision and reject its open quotes?')))return;if(action==='publish'){const current=rules.value.find(candidate=>candidate.familyId===r.familyId&&candidate.status==='PUBLISHED');if(current&&!confirm(t('Publishing this draft will retire the current published revision atomically.')))return;busy.value=true;try{await api.transitionPromotion(r.id,action,current?.id);await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false};return}busy.value=true;try{await api.transitionPromotion(r.id,action);await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="operations-page promotions-page"><header class="page-heading"><h1>{{t('Promotion revisions')}}</h1><p>{{t('Published financial rules are immutable. Create a new revision to change an offer.')}}</p></header><p v-if="error" class="form-error" role="alert">{{error}}</p>
<form class="promotion-editor" @submit.prevent="save"><label>{{t('Acquisition mode')}}<select v-model="mode" :disabled="!!familyId"><option>AUTOMATIC</option><option>CODE</option><option>CLAIMABLE</option></select><small v-if="familyId">{{t('Acquisition mode is immutable for an existing family.')}}</small></label><label v-if="mode==='CODE'">{{t('Voucher code')}}<input v-model="code" :disabled="!!familyId" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,31}" aria-describedby="voucher-code-help"><small id="voucher-code-help">{{t('Use 3–32 letters, numbers, underscores, or hyphens.')}}</small></label><label v-if="isVoucher" class="check-row"><input v-model="discoverable" type="checkbox">{{t('Publicly discoverable')}}<small>{{t('Visibility does not grant eligibility or usage.')}}</small></label><label>{{t('Name')}}<input v-model="name" required maxlength="120"></label><label>{{t('Benefit type')}}<select v-model="type"><option v-for="effect in effects" :key="effect">{{effect}}</option></select></label><label v-if="type!=='FREE_SHIPPING'">{{type.endsWith('PERCENT')?t('Percentage'):t('Amount (VND)')}}<input v-model.number="value" type="number" min="1" :max="type.endsWith('PERCENT')?100:9999999999" required></label><label v-if="isVoucher">{{t('Customer summary')}}<input v-model="summary" required maxlength="240"></label><label v-if="isVoucher">{{t('Customer terms')}}<textarea v-model="terms" required maxlength="1000"></textarea></label><label>{{t('Minimum spend')}}<input v-model.number="minimum" type="number" min="0"></label><label v-if="layer==='ITEM'">{{t('Buy quantity')}}<input v-model.number="buy" type="number" min="1"></label><label>{{t('Global usage limit')}}<input v-model.number="globalLimit" type="number" min="1"></label><label>{{t('Per-customer limit')}}<input v-model.number="customerLimit" type="number" min="1"></label><label>{{t('Priority')}}<input v-model.number="priority" type="number" required></label><label>{{t('Starts')}}<input v-model="validFrom" type="datetime-local" required></label><label>{{t('Ends')}}<input v-model="validTo" type="datetime-local"></label><fieldset v-if="layer==='ITEM'"><legend>{{t('Eligible products')}}</legend><label v-for="p in products" :key="p.id" class="check-row"><input v-model="productIds" type="checkbox" :value="p.id">{{p.name}}</label></fieldset><button :disabled="busy||layer==='ITEM'&&!productIds.length">{{busy?t('Saving…'):t(editingId?'Save draft':familyId?'Create new revision':'Create draft')}}</button></form>
<div class="table-shell"><table><thead><tr><th>{{t('Promotion')}}</th><th>{{t('Acquisition')}}</th><th>{{t('Revision')}}</th><th>{{t('Benefit')}}</th><th>{{t('Priority')}}</th><th>{{t('State')}}</th><th>{{t('Actions')}}</th></tr></thead><tbody><tr v-for="r in rules" :key="r.id"><td><strong>{{r.name}}</strong><br><small>{{r.familyId}}</small><br><small v-if="r.customerSummary">{{r.customerSummary}}</small></td><td>{{r.acquisitionMode}}<br><code v-if="r.normalizedCode">{{r.normalizedCode}}</code><br><small>{{r.publiclyDiscoverable?t('Publicly discoverable'):t('Private')}}</small></td><td>{{r.revisionNumber}}</td><td>{{r.effectType}}<br>{{r.percentageValue?`${r.percentageValue}%`:r.fixedAmount?formatVnd(r.fixedAmount):t('Shipping fee')}}</td><td>{{r.priority}}</td><td><strong>{{r.status}}</strong></td><td><button v-if="r.status==='DRAFT'" type="button" :disabled="busy" @click="edit(r)">{{t('Edit')}}</button><button v-if="r.status==='DRAFT'" type="button" :disabled="busy" @click="transition(r,'publish')">{{t('Publish')}}</button><button v-if="r.status==='PUBLISHED'" type="button" :disabled="busy" @click="revise(r)">{{t('Create new revision')}}</button><button v-if="r.status==='PUBLISHED'" type="button" :disabled="busy" @click="transition(r,'retire')">{{t('Retire')}}</button><button v-if="r.status==='PUBLISHED'" type="button" :disabled="busy" class="danger-button" @click="transition(r,'invalidate')">{{t('Invalidate')}}</button></td></tr></tbody></table></div></div></template>
